css:
#dyn-mosaic-theme[data-theme="tmpl-live-mosaic"]  {
  overflow: hidden;
  background:
    radial-gradient(120% 90% at 50% -10%, rgba(139, 92, 255, 0.1), transparent 55%),
    radial-gradient(120% 80% at 50% 110%, rgba(255, 62, 127, 0.09), transparent 55%),
    #05060a;
}
#dyn-mosaic-theme[data-theme="tmpl-live-mosaic"] .dyn-live-world  {
  position: absolute;
  top: 0;
  left: 0;
  display: grid;
  transform-origin: 0 0;
  will-change: transform;
}
#dyn-mosaic-theme[data-theme="tmpl-live-mosaic"] .dyn-live-tile  {
  position: relative;
  overflow: hidden;
  border-radius: 12px;
  background: #11141c;
  box-shadow: inset 0 0 0 1px rgba(255, 255, 255, 0.03);
  transition: opacity 360ms ease, filter 360ms ease;
}
#dyn-mosaic-theme[data-theme="tmpl-live-mosaic"] .dyn-live-tile img  {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  object-fit: cover;
  display: block;
  transform-origin: 50% 50%;
  will-change: transform, opacity;
  backface-visibility: hidden;
  transition: opacity 300ms ease;
}
#dyn-mosaic-theme[data-theme="tmpl-live-mosaic"] .dyn-live-tile.is-dormant  {
  opacity: 0.16;
  filter: saturate(0.75) brightness(0.75);
}
#dyn-mosaic-theme[data-theme="tmpl-live-mosaic"] .dyn-live-tile.is-dormant img  {
  opacity: 0;
}
#dyn-mosaic-theme[data-theme="tmpl-live-mosaic"] .dyn-live-tile.is-pending img  {
  opacity: 0;
  transform: scale(0.28) rotate(-8deg);
}
#dyn-mosaic-theme[data-theme="tmpl-live-mosaic"] .dyn-live-tile.is-pending::after  {
  content: "";
  position: absolute;
  inset: 0;
  background: linear-gradient(110deg, #11141c 30%, #1c2130 50%, #11141c 70%);
  background-size: 220% 100%;
  animation: dyn-shimmer 1.2s ease-in-out infinite;
}
@keyframes dyn-shimmer  {
  0%  {
   background-position: 140% 0;
   }
  100%  {
   background-position: -140% 0;
   }
}
#dyn-mosaic-theme[data-theme="tmpl-live-mosaic"] .dyn-live-tile.is-arrive img  {
  animation: dyn-live-pop 0.58s cubic-bezier(0.34, 1.56, 0.64, 1);
}
@keyframes dyn-live-pop  {
  0%  {
   opacity: 0;
   transform: scale(0.28) rotate(-8deg);
   }
  60%  {
   opacity: 1;
   }
  100%  {
   opacity: 1;
   transform: scale(1) rotate(0);
   }
}
#dyn-mosaic-theme[data-theme="tmpl-live-mosaic"] .dyn-live-tile.is-flash::before  {
  content: "";
  position: absolute;
  inset: 0;
  border-radius: 12px;
  box-shadow: 0 0 0 3px #ff3e7f, 0 0 22px 4px rgba(255, 62, 127, 0.55);
  animation: dyn-ring-fade 1.1s ease-out forwards;
  pointer-events: none;
  z-index: 2;
}
@keyframes dyn-ring-fade  {
  0%  {
   opacity: 1;
   }
  100%  {
   opacity: 0;
   }
}
#dyn-mosaic-theme[data-theme="tmpl-live-mosaic"] .dyn-live-vignette  {
  position: absolute;
  inset: 0;
  pointer-events: none;
  z-index: 5;
  background: radial-gradient(120% 120% at 50% 50%, transparent 58%, rgba(0, 0, 0, 0.45) 100%);
}

@keyframes dyn-shimmer  {
  0%  {
   background-position: 140% 0;
   }
  100%  {
   background-position: -140% 0;
   }
}
@keyframes dyn-live-pop  {
  0%  {
   opacity: 0;
   transform: scale(0.28) rotate(-8deg);
   }
  60%  {
   opacity: 1;
   }
  100%  {
   opacity: 1;
   transform: scale(1) rotate(0);
   }
}
@keyframes dyn-ring-fade  {
  0%  {
   opacity: 1;
   }
  100%  {
   opacity: 0;
   }
}
#dyn-mosaic-theme[data-theme="tmpl-live-mosaic"] .dyn-card  {
  border-radius: 12px;
  background: #11141c;
  box-shadow: inset 0 0 0 1px rgba(255,255,255,.03);
  overflow: hidden;
}
#dyn-mosaic-theme[data-theme="tmpl-live-mosaic"] .dyn-card:nth-child(5n)  {
   opacity: .2;
   filter: saturate(.7) brightness(.7);
   }
#dyn-mosaic-theme[data-theme="tmpl-live-mosaic"] .dyn-live-vignette  {
  position: absolute;
   inset: 0;
   pointer-events: none;
   z-index: 5;
  background: radial-gradient(120% 120% at 50% 50%, transparent 58%, rgba(0,0,0,.45) 100%);
}
